MATCH (f:File)
WHERE NOT EXISTS { MATCH (f)-[r:IMPORTS|RE_EXPORTS]->(:File) WHERE NOT coalesce(r.viaReExport, false) }
  AND NOT EXISTS { MATCH (:File)-[r:IMPORTS|RE_EXPORTS]->(f) WHERE NOT coalesce(r.viaReExport, false) }
  AND NOT f.isBarrel
RETURN count(f) AS cnt

